1	package net.officefloor.hq.app.claim;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.List;
7	import net.officefloor.hq.app.Audit;
8	import net.officefloor.hq.app.period.Period;
9	import net.officefloor.hq.app.period.PeriodClosedException;
10	import net.officefloor.hq.app.period.PeriodRepository;
11	import net.officefloor.hq.app.person.Person;
12	import net.officefloor.hq.app.person.PersonNotFoundException;
13	import net.officefloor.hq.app.person.PersonRetiredException;
14	import net.officefloor.hq.app.person.PersonRepository;
15	import net.officefloor.hq.app.rate.Rate;
16	import net.officefloor.hq.app.rate.RateService;
17	import net.officefloor.hq.app.rollup.RollupService;
18	import net.officefloor.hq.app.setting.Role;
19	import net.officefloor.hq.app.setting.SettingService;
20	import net.officefloor.hq.app.sheet.Sheet;
21	import net.officefloor.hq.app.sheet.SheetService;
22	import org.springframework.stereotype.Service;
23	import org.springframework.transaction.annotation.Transactional;
24	
25	/**
26	 * The claims on a sheet: listed newest first, added to a person and edited one at a time. A claim
27	 * given no date takes the sheet's today. Its due-by is fixed when it is added: its date plus the terms
28	 * in force on that date of its person's grade then (else the sheet's terms in force on it); it does not
29	 * move when its date or the terms change later. A claim is added as DRAFT and moves through its statuses
30	 * as {@link ClaimStatus} allows; a change it does not allow is refused. Opening a claim gives it
31	 * the sheet's next number (or, while the sheet numbers by period, the next within its period), which it
32	 * keeps when voided and is never given again. Only a DRAFT claim
33	 * can be edited; an OPEN one is changed by voiding it and adding a new one. Settling it
34	 * fixes its due at its figure (the due bound by a statement, else its person's grade rate of the
35	 * moment on the claim's date) with its late charge of the moment frozen in; with no figure it
36	 * stays live. A steward can re-settle a SETTLED claim at the figure it would have today as an open claim
37	 * bound by no statement. The user who opened a claim cannot settle it, and a clerk cannot settle one whose
38	 * due is above the sheet's clerk limit (a steward can). No claim dated inside a closed period can
39	 * be added, edited (to or from such a date), opened, settled, re-settled or voided. No claim can be added
40	 * or edited to a date after its person's retirement date. A claim with a negative amount is a
41	 * correction: it must name, by number, a SETTLED claim of the same person; only a correction may name one.
42	 */
43	@Service
44	public class ClaimService {
45	
46	    private final ClaimRepository claims;
47	    private final PersonRepository people;
48	    private final RateService rates;
49	    private final SheetService sheets;
50	    private final RollupService rollup;
51	    private final PeriodRepository periods;
52	    private final SettingService settings;
53	    private final Audit audit;
54	
55	    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
56	            RollupService rollup, PeriodRepository periods, SettingService settings, Audit audit) {
57	        this.settings = settings;
58	        this.periods = periods;
59	        this.claims = claims;
60	        this.people = people;
61	        this.rates = rates;
62	        this.sheets = sheets;
63	        this.rollup = rollup;
64	        this.audit = audit;
65	    }
66	
67	    @Transactional(readOnly = true)
68	    public List<Claim> list(String sheetId) {
69	        return claims.findBySheetIdOrderByListedDesc(sheetId);
70	    }
71	
72	    @Transactional
73	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
74	            String corrects) {
75	        // The snapshot locks the sheet first, so the person is read as retired by any retirement before.
76	        RollupService.Snapshot before = rollup.snapshot(sheetId);
77	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
78	        LocalDate on = dateOrToday(sheetId, date);
79	        refuseIfClosed(sheetId, on);
80	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
81	        refuseUnlessCorrects(sheetId, personId, amount, corrects);
82	        LocalDate dueBy = on.plusDays(settings.termsFor(sheetId, person.gradeOn(on), on));
83	        Claim draft = new Claim(sheetId, personId, amount, on, note, dueBy);
84	        draft.setCorrects(corrects);
85	        Claim claim = claims.saveAndFlush(draft);
86	        logStatus(sheetId, user, person, claim);
87	        claim = claims.saveAndFlush(claim);
88	        record("CLAIM_ADDED", sheetId, user, person, claim);
89	        rollup.recordChanges(sheetId, user, before);
90	        return claim;
91	    }
92	
93	    @Transactional
94	    public Claim edit(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
95	            String corrects) {
96	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
97	        if (claim.getStatus() != ClaimStatus.DRAFT) {
98	            throw new ClaimStatusRefusedException();
99	        }
100	        RollupService.Snapshot before = rollup.snapshot(sheetId);
101	        LocalDate on = dateOrToday(sheetId, date);
102	        refuseIfClosed(sheetId, claim.getDate());
103	        refuseIfClosed(sheetId, on);
104	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
105	        if (!person.mayClaimOn(on)) throw new PersonRetiredException();
106	        refuseUnlessCorrects(sheetId, person.getId(), amount, corrects);
107	        claim.setAmount(amount);
108	        claim.setCorrects(corrects);
109	        claim.setDate(on);
110	        claim.setNote(note);
111	        Claim saved = claims.saveAndFlush(claim);
112	        record("CLAIM_EDITED", sheetId, user, person, saved);
113	        rollup.recordChanges(sheetId, user, before);
114	        return saved;
115	    }
116	
117	    @Transactional
118	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next) {
119	        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
120	        // once no other open on the sheet is under way; a refusal rolls the number back.
121	        Sheet numbering = next == ClaimStatus.OPEN ? sheets.lockForNumbering(sheetId) : null;
122	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
123	        if (!claim.getStatus().canBecome(next)) {
124	            throw new ClaimStatusRefusedException();
125	        }
126	        if (next == ClaimStatus.SETTLED && user.strip().equals(claim.getOpenedBy())) {
127	            throw new ClaimSettledByOpenerException();
128	        }
129	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
130	        // Settling freezes the late charge of the moment into the settled due.
131	        BigDecimal settling = next == ClaimStatus.SETTLED ? chargedFigureOf(sheetId, person, claim) : null;
132	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settling)) next = ClaimStatus.PENDING;
133	        RollupService.Snapshot before = rollup.snapshot(sheetId);
134	        refuseIfClosed(sheetId, claim.getDate());
135	        switch (next) {
136	            case OPEN -> {
137	                number(numbering, claim);
138	                claim.setOpenedBy(user.strip());
139	            }
140	            case SETTLED -> claim.setSettledDue(settling);
141	            default -> {}
142	        }
143	        claim.setStatus(next);
144	        logStatus(sheetId, user, person, claim);
145	        Claim saved = claims.saveAndFlush(claim);
146	        String event = switch (next) {
147	            case OPEN -> "CLAIM_OPENED";
148	            case PENDING -> "CLAIM_PENDING";
149	            case SETTLED -> "CLAIM_SETTLED";
150	            case VOID -> "CLAIM_VOIDED";
151	            case DRAFT -> throw new IllegalStateException();
152	        };
153	        String due = next == ClaimStatus.SETTLED
154	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
155	                : "";
156	        record(event, sheetId, user, person, saved, saved.getNumber(), due);
157	        rollup.recordChanges(sheetId, user, before);
158	        return saved;
159	    }
160	
161	    /** A steward other than its opener approves a PENDING claim: SETTLED, its due fixed at its live due now. */
162	    @Transactional
163	    public Claim approve(String sheetId, String user, Long id) {
164	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
165	        RollupService.Snapshot before = rollup.snapshot(sheetId);
166	        Claim claim = pendingForSteward(sheetId, user, id);
167	        if (user.strip().equals(claim.getOpenedBy())) throw new ClaimApprovedByOpenerException();
168	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
169	        refuseIfClosed(sheetId, claim.getDate());
170	        claim.setSettledDue(chargedFigureOf(sheetId, person, claim));
171	        claim.setStatus(ClaimStatus.SETTLED);
172	        logStatus(sheetId, user, person, claim);
173	        Claim saved = claims.saveAndFlush(claim);
174	        record("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber(), " due="
175	                + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString()));
176	        rollup.recordChanges(sheetId, user, before);
177	        return saved;
178	    }
179	
180	    /** A steward rejects a PENDING claim with a reason: OPEN again, bound by its person's last statement if it was. */
181	    @Transactional
182	    public Claim reject(String sheetId, String user, Long id, String reason) {
183	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
184	        RollupService.Snapshot before = rollup.snapshot(sheetId);
185	        Claim claim = pendingForSteward(sheetId, user, id);
186	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
187	        refuseIfClosed(sheetId, claim.getDate());
188	        claim.setStatus(ClaimStatus.OPEN);
189	        logStatus(sheetId, user, person, claim);
190	        Claim saved = claims.saveAndFlush(claim);
191	        record("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber(), " reason=" + reason);
192	        rollup.recordChanges(sheetId, user, before);
193	        return saved;
194	    }
195	
196	    /**
197	     * A steward re-settles a SETTLED claim: its due fixed again at the figure it would have today as an
198	     * open claim bound by no statement (the rate, grade, floor and late percent in force on its date, the
199	     * late charge as of today). Refused for anyone
200	     * else, a claim in any other status, or one dated inside a closed period.
201	     */
202	    @Transactional
203	    public Claim resettle(String sheetId, String user, Long id) {
204	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
205	        RollupService.Snapshot before = rollup.snapshot(sheetId);
206	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
207	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusRefusedException();
208	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
209	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
210	        refuseIfClosed(sheetId, claim.getDate());
211	        BigDecimal old = claim.getSettledDue();
212	        BigDecimal figure = LateCharge.withChargeAsOpen(claim, dueOf(sheetId, person, claim), sheets.today(sheetId),
213	                settings.latePctOn(sheetId, claim.getDate()), roundingOf(sheetId, claim));
214	        claim.setSettledDue(figure);
215	        logStatus(sheetId, user, person, claim);
216	        Claim saved = claims.saveAndFlush(claim);
217	        record("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
218	                " old=" + figureText(old) + " new=" + figureText(figure));
219	        rollup.recordChanges(sheetId, user, before);
220	        return saved;
221	    }
222	
223	    /** A fixed due as an audit line has it: two decimals, or n/a when none. */
224	    private static String figureText(BigDecimal due) {
225	        return due == null ? "n/a" : due.setScale(2).toPlainString();
226	    }
227	
228	    /**
229	     * A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number
230	     * and date, loses any figure a statement bound it to (live again until its new person's next
231	     * statement), and is listed as its new person's newest claim. A SETTLED or VOID claim cannot move,
232	     * nor one dated inside a closed period, nor one dated after its new person's retirement date.
233	     */
234	    @Transactional
235	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
236	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
237	        RollupService.Snapshot before = rollup.snapshot(sheetId);
238	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
239	        ClaimStatus status = claim.getStatus();
240	        if (status != ClaimStatus.DRAFT && !status.isOpen()) throw new ClaimStatusRefusedException();
241	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
242	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
243	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
244	        if (from.getId().equals(to.getId())) throw new ClaimReassignRefusedException();
245	        refuseIfClosed(sheetId, claim.getDate());
246	        if (!to.mayClaimOn(claim.getDate())) throw new PersonRetiredException();
247	        claim.unstate();
248	        claim.moveTo(to.getId(), claims.nextListed());
249	        Claim saved = claims.saveAndFlush(claim);
250	        record("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber(),
251	                " from=" + from.getName() + " to=" + to.getName());
252	        rollup.recordChanges(sheetId, user, before);
253	        return saved;
254	    }
255	
256	    /** The PENDING claim a steward approves or rejects; refused when not PENDING or not a steward. */
257	    private Claim pendingForSteward(String sheetId, String user, Long id) {
258	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
259	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusRefusedException();
260	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
261	        return claim;
262	    }
263	
264	    /**
265	     * Give an opened claim its number: the sheet's next, or while the sheet numbers by period, the next
266	     * within the period its date falls in (in no period: the next in the sheet's X sequence).
267	     */
268	    private void number(Sheet sheet, Claim claim) {
269	        if (!sheet.numbersByPeriod()) {
270	            claim.setNumber(sheet.nextClaimNumber());
271	            return;
272	        }
273	        String period = periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
274	                .filter(p -> p.contains(claim.getDate()))
275	                .map(Period::getName)
276	                .findFirst().orElse("");
277	        claim.setNumberWithin(period, claims.lastNumberWithin(sheet.getId(), period) + 1);
278	    }
279	
280	    /**
281	     * A claim's figure now: the due fixed when it was settled, else the due bound by its person's
282	     * last statement, else its live due; null when it has none.
283	     */
284	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
285	        if (claim.getSettledDue() != null) return claim.getSettledDue();
286	        if (claim.isBound()) return claim.getStatedDue();
287	        return dueOf(sheetId, person, claim);
288	    }
289	
290	    /**
291	     * A claim's due now: its figure, with the late charge on top while it is overdue; null when it
292	     * has none. A statement binds the figure, never the charge.
293	     */
294	    public BigDecimal chargedFigureOf(String sheetId, Person person, Claim claim) {
295	        BigDecimal figure = figureOf(sheetId, person, claim);
296	        if (claim.getSettledDue() != null) return figure;
297	        return LateCharge.withCharge(claim, figure, sheets.today(sheetId),
298	                settings.latePctOn(sheetId, claim.getDate()), roundingOf(sheetId, claim));
299	    }
300	
301	    /** How the claim's live figures round: by its date, or a correction's by its corrected claim's ({@link Rounding}). */
302	    private RoundingMode roundingOf(String sheetId, Claim claim) {
303	        LocalDate basis = Rounding.basisOf(claim,
304	                Rounding.datesByNumber(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId())));
305	        return Rounding.of(basis, settings.policyDate(sheetId), sheets.today(sheetId));
306	    }
307	
308	    /**
309	     * A claim's live due: its amount times the rate on its date of its person's grade in force on it, rounded to
310	     * cents as {@link Rounding} has it, and at least the sheet's floor in force on its date unless a correction; null with no rate.
311	     */
312	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
313	        BigDecimal floor = claim.isCorrection() ? null : settings.floorOn(sheetId, claim.getDate());
314	        RoundingMode rounding = roundingOf(sheetId, claim);
315	        return rates.on(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
316	                .map(Rate::getPct)
317	                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
318	                .map(due -> floor == null ? due : due.max(floor))
319	                .orElse(null);
320	    }
321	
322	    /** Log the status the claim now has: by the user on the sheet's today, with its due at this moment. */
323	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
324	        claim.logStatus(user.strip(), sheets.today(sheetId), chargedFigureOf(sheetId, person, claim));
325	    }
326	
327	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
328	        record(event, sheetId, user, person, claim, claim.getNumber(), "");
329	    }
330	
331	    /** A claim's audit line; one about a claim with a number has it, then any extra fields. */
332	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number,
333	            String extra) {
334	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user.strip() + " person=" + person.getName()
335	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
336	                + (number != null ? " number=" + number : "") + extra);
337	    }
338	
339	    /**
340	     * Refuse a correction that names no SETTLED claim of its person by number, and a claim that names
341	     * one but is not a correction.
342	     */
343	    private void refuseUnlessCorrects(String sheetId, Long personId, BigDecimal amount, String corrects) {
344	        if (amount.signum() >= 0) {
345	            if (corrects != null) throw new CorrectionRefusedException();
346	            return;
347	        }
348	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
349	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
350	        if (!settled) throw new CorrectionRefusedException();
351	    }
352	
353	    /** Whether a clerk settles a claim whose due is above the clerk limit; a due of n/a is within any. */
354	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
355	        if (settings.roleOf(sheetId, user) == Role.STEWARD) return false;
356	        BigDecimal limit = settings.clerkLimit(sheetId);
357	        return limit != null && due != null && due.compareTo(limit) > 0;
358	    }
359	
360	    /** Refuse a change to a claim dated inside a closed period; the caller holds the sheet's lock. */
361	    private void refuseIfClosed(String sheetId, LocalDate date) {
362	        if (periods.closedOn(sheetId, date)) throw new PeriodClosedException();
363	    }
364	
365	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
366	        return date != null ? date : sheets.today(sheetId);
367	    }
368	}
