1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, inject, input, output, signal } from '@angular/core';
3	import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
4	import { firstValueFrom } from 'rxjs';
5	import { Late, Session } from '../../core/session';
6	import { Period, closedOn, periodOn } from '../periods/periods';
7	import { NA, dueCents } from '../rates/rates';
8	
9	/**
10	 * DRAFT when added, then OPEN, then SETTLED; a clerk's settling above the clerk limit makes it
11	 * PENDING until a steward approves it (SETTLED) or rejects it (OPEN). A DRAFT, OPEN or PENDING
12	 * claim can be made VOID.
13	 */
14	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
15	
16	/** A status change a claim's buttons ask for. */
17	type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle';
18	
19	export interface Claim {
20	  id: number;
21	  personId: number;
22	  /** Always two decimals, e.g. "2.50". */
23	  amount: string;
24	  date: string;
25	  note: string;
26	  status: ClaimStatus;
27	  /** Given when the claim is opened and kept once VOID; null while DRAFT. */
28	  /** The sheet-wide number, or <period name>-<n> (X-<n> in no period) when numbered by period; null while DRAFT. */
29	  number: string | null;
30	  /** The due fixed when it was settled, two decimals; null while its due is live. */
31	  settledDue: string | null;
32	  /** The user who opened it; null while DRAFT. They cannot settle it. */
33	  openedBy: string | null;
34	  /** Bound by its person's last statement, to the due it had then; not while PENDING, when its due is live. */
35	  stated: boolean;
36	  /** The due bound by its person's last statement, two decimals; null while not stated, or stated with none. */
37	  statedDue: string | null;
38	  /** A correction's (negative amount's) number of the SETTLED claim it corrects; null for any other claim. */
39	  corrects: string | null;
40	  /** The date it is due by (yyyy-mm-dd), fixed when it was added; it does not move with its date or the terms. */
41	  dueBy: string;
42	  /** Its status log, oldest first: a line for each status it has had, DRAFT when added. */
43	  log: ClaimLogLine[];
44	}
45	
46	/** A status a claim was given, by whom, on the sheet's today then, with its due then (null: none). */
47	export interface ClaimLogLine {
48	  status: ClaimStatus;
49	  by: string;
50	  date: string;
51	  due: string | null;
52	}
53	
54	/** A person's rate on a date: the rate then of the grade they had then, or null when it has none. */
55	export type PctOn = (date: string) => string | null;
56	
57	/** The sheet's floor in force on a date, in cents. */
58	export type FloorOn = (date: string) => number;
59	
60	/** Open: OPEN, or PENDING, which is handled like it. */
61	export function isOpen(c: Claim): boolean {
62	  return c.status === 'OPEN' || c.status === 'PENDING';
63	}
64	
65	/** Only open (OPEN or PENDING) and SETTLED claims count toward what is claimed and due. */
66	export function counts(c: Claim): boolean {
67	  return isOpen(c) || c.status === 'SETTLED';
68	}
69	
70	/** Whether its due is now bound by its person's last statement: stated and not PENDING. */
71	export function isBound(c: Claim): boolean {
72	  return c.stated && c.status !== 'PENDING';
73	}
74	
75	/**
76	 * Whether the claim counts for its person, given whether its date falls within one of their holds:
77	 * an open claim dated within a hold does not, unless bound by a statement.
78	 */
79	export function countsFor(c: Claim, heldOnDate: boolean): boolean {
80	  return counts(c) && (!heldOnDate || !isOpen(c) || isBound(c));
81	}
82	
83	/** A claim's amount as cents, so sums are exact; a correction's is negative. */
84	export function cents(amount: string): number {
85	  const negative = amount.startsWith('-');
86	  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
87	  const size = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
88	  return negative ? -size : size;
89	}
90	
91	/** A correction: a claim with a negative amount. Its due has no floor and no late charge. */
92	export function isCorrection(c: Claim): boolean {
93	  return cents(c.amount) < 0;
94	}
95	
96	/**
97	 * The date a claim's live figures round by: a correction's corrected claim's date (found among its
98	 * person's claims, `theirs`), else its own.
99	 */
100	export function roundsOn(c: Claim, theirs: Claim[]): string {
101	  if (c.corrects === null) return c.date;
102	  return theirs.find((o) => o.number === c.corrects)?.date ?? c.date;
103	}
104	
105	/** Whether a claim rounding by the given date rounds half up: dated before the policy date; else half to even. */
106	function halfUp(basis: string, late: Late): boolean {
107	  return late.policy !== null && basis < late.policy;
108	}
109	
110	/**
111	 * A claim's due in cents: the due fixed when it was settled (late charge frozen in), else its figure
112	 * — the due bound by its person's last statement, else its amount times its person's rate on its
113	 * date (as `pctOn` gives it), at least the floor in force on its date (`floorOn`, in cents) unless a correction —
114	 * with its late charge (by the late percent in force on its date) on top;
115	 * null when it has none. Its live figures round by the date `basis` (see {@link roundsOn}).
116	 */
117	export function claimDueCents(c: Claim, pctOn: PctOn, floorOn: FloorOn, late: Late, basis: string): number | null {
118	  if (c.settledDue !== null) return cents(c.settledDue);
119	  const up = halfUp(basis, late);
120	  const figure = figureCents(c, pctOn, floorOn, up);
121	  return figure === null ? null : figure + lateChargeCents(c, figure, late, up);
122	}
123	
124	/** A claim's figure in cents: the due bound by its person's last statement, else its floored live due. */
125	function figureCents(c: Claim, pctOn: PctOn, floorOn: FloorOn, halfUp: boolean): number | null {
126	  if (isBound(c)) return c.statedDue === null ? null : cents(c.statedDue);
127	  const pct = pctOn(c.date);
128	  if (pct === null) return null;
129	  const due = dueCents(cents(c.amount), pct, halfUp);
130	  return isCorrection(c) ? due : Math.max(due, floorOn(c.date));
131	}
132	
133	/**
134	 * The late charge in cents on an overdue claim with the given figure: the late percent in force on its date of it for
135	 * every full 30 days past its due-by, rounded like a due; 0 when not overdue or a correction. Never bound
136	 * by a statement.
137	 */
138	export function lateChargeCents(c: Claim, figureCents: number, late: Late, halfUp: boolean): number {
139	  if (late.today === null || isCorrection(c) || !isOverdue(c, late.today)) return 0;
140	  const days = Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${c.dueBy}T00:00:00Z`)) / 86_400_000);
141	  return dueCents(figureCents * Math.floor(days / 30), late.pctOn(c.date), halfUp);
142	}
143	
144	/** Overdue: OPEN or PENDING with its due-by before the sheet's today. */
145	export function isOverdue(c: Claim, today: string | null): boolean {
146	  return isOpen(c) && today !== null && c.dueBy < today;
147	}
148	
149	/** Why a change to a claim dated inside a closed period is refused. */
150	const CLOSED = 'No claim dated inside a closed period can be changed.';
151	
152	/** Why a claim dated after its person's retirement date is refused. */
153	export const RETIRED = 'No claim can be dated after its person\'s retirement date.';
154	
155	/** Cents as an amount with two decimals; a minus sign when negative. */
156	export function money(cents: number): string {
157	  const size = Math.abs(cents);
158	  return `${cents < 0 ? '-' : ''}${Math.floor(size / 100)}.${String(size % 100).padStart(2, '0')}`;
159	}
160	
161	/** What each action makes of a claim, for why it was refused. */
162	const PAST: Record<ClaimAction, string> = {
163	  open: 'opened', settle: 'settled', void: 'voided', approve: 'approved', reject: 'rejected',
164	  resettle: 're-settled',
165	};
166	
167	/** Why a claim's correction is refused. */
168	const CORRECTION = 'A negative amount is a correction: name the number of a SETTLED claim of this person that it corrects.';
169	
170	/** Why a claim cannot be edited: only a DRAFT can; an OPEN or PENDING one is voided and added again. */
171	function notEditable(status: ClaimStatus | undefined): string {
172	  return status === 'OPEN' || status === 'PENDING'
173	    ? `An ${status} claim cannot be edited; void it and add a new one.`
174	    : `${status ? 'A ' + status : 'This'} claim cannot be edited; only a DRAFT can.`;
175	}
176	
177	// One person's claims, newest first, with one form to add a claim or edit one, and buttons to
178	// open, settle or void each claim, approve or reject (with a reason) a PENDING one, re-settle a SETTLED one, move one to another person, and a checkbox to select each for a bulk change.
179	@Component({
180	  selector: 'app-claims',
181	  imports: [ReactiveFormsModule],
182	  template: `
183	    <form [formGroup]="form" (ngSubmit)="save()" [attr.aria-label]="(editingId() === null ? 'Add claim for ' : 'Edit claim for ') + personName()">
184	      <label [for]="fieldId('amount')">Amount</label>
185	      <input [id]="fieldId('amount')" data-testid="claim-form-amount" formControlName="amount" inputmode="decimal" />
186	      <label [for]="fieldId('date')">Date</label>
187	      <input [id]="fieldId('date')" type="date" data-testid="claim-form-date" formControlName="date" />
188	      <label [for]="fieldId('note')">Note</label>
189	      <input [id]="fieldId('note')" data-testid="claim-form-note" formControlName="note" />
190	      <label [for]="fieldId('corrects')">Corrects claim no.</label>
191	      <input [id]="fieldId('corrects')" data-testid="claim-form-corrects" formControlName="corrects" />
192	      <button type="submit" data-testid="claim-form-submit">{{ editingId() === null ? 'Add claim' : 'Save claim' }}</button>
193	      @if (error()) {
194	        <p role="alert" class="error" data-testid="claim-form-error">{{ error() }}</p>
195	      }
196	    </form>
197	    <ul [attr.aria-label]="'Claims for ' + personName()">
198	      @for (c of claims(); track c.id) {
199	        <li [attr.data-testid]="'claim-row-' + c.id">
200	          <input type="checkbox" data-testid="claim-select" [checked]="selected().has(c.id)"
201	                 (change)="toggled.emit({ id: c.id, checked: $any($event.target).checked })"
202	                 [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date" />
203	          <span>No. <span data-testid="claim-number">{{ c.number ?? '' }}</span></span>
204	          <span data-testid="claim-amount">{{ c.amount }}</span>
205	          <span data-testid="claim-date">{{ c.date }}</span>
206	          <span data-testid="claim-note">{{ c.note }}</span>
207	          <span>Period <span data-testid="claim-period">{{ periodOf(c) }}</span></span>
208	          <span>Due <span data-testid="claim-due">{{ dueOf(c) }}</span></span>
209	          <span data-testid="claim-status">{{ c.status }}</span>
210	          <span>Opened by <span data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</span></span>
211	          <span>Stated <span data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</span></span>
212	          <span>Due by <span data-testid="claim-due-by">{{ c.dueBy }}</span></span>
213	          <span>Overdue <span data-testid="claim-overdue">{{ overdueOf(c) ? 'yes' : 'no' }}</span></span>
214	          <span>Corrects <span data-testid="claim-corrects">{{ c.corrects ?? '' }}</span></span>
215	          <ol [attr.aria-label]="'Status log of claim of ' + c.amount + ' on ' + c.date">
216	            @for (line of c.log; track $index) {
217	              <li data-testid="claim-log-line">{{ line.status }} by {{ line.by }} on {{ line.date }} due={{ line.due ?? na }}</li>
218	            }
219	          </ol>
220	          <button type="button" data-testid="claim-open" (click)="act(c, 'open')"
221	                  [attr.aria-label]="'Open claim of ' + c.amount + ' on ' + c.date">Open</button>
222	          <button type="button" data-testid="claim-settle" (click)="act(c, 'settle')"
223	                  [attr.aria-label]="'Settle claim of ' + c.amount + ' on ' + c.date">Settle</button>
224	          <button type="button" data-testid="claim-void" (click)="act(c, 'void')"
225	                  [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
