227	                  [attr.aria-label]="'Approve claim of ' + c.amount + ' on ' + c.date">Approve</button>
228	          <button type="button" data-testid="claim-resettle" (click)="act(c, 'resettle')"
229	                  [attr.aria-label]="'Re-settle claim of ' + c.amount + ' on ' + c.date">Re-settle</button>
