257	export class Claims {
258	  private readonly http = inject(HttpClient);
259	  private readonly session = inject(Session);
260	
261	  readonly personId = input.required<number>();
262	  readonly personName = input.required<string>();
263	  readonly claims = input.required<Claim[]>();
264	  /** The person's rate on a date, of the grade they had then. */
265	  readonly pctOn = input.required<PctOn>();
266	  /** The sheet's periods, for the one each claim's date falls in. */
267	  readonly periods = input.required<Period[]>();
268	  /** A claim added, edited or given a new status, as the store now holds it. */
269	  readonly saved = output<Claim>();
270	  /** The other people on the sheet a claim may be moved to. */
271	  readonly others = input.required<{ id: number; name: string }[]>();
272	  /** A claim moved to another person, as the store now holds it. */
273	  readonly moved = output<Claim>();
274	  /** The ids of the claims selected for a bulk change. */
275	  readonly selected = input.required<ReadonlySet<number>>();
276	  /** A claim's checkbox ticked or cleared. */
277	  readonly toggled = output<{ id: number; checked: boolean }>();
278	
279	  protected readonly na = NA;
280	  protected readonly editingId = signal<number | null>(null);
281	  /** A submit is under way; another one waits for its answer rather than storing twice. */
282	  private saving = false;
283	  protected readonly error = signal('');
284	  /** The error from the last action on a claim's row, if it was refused. */
285	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
286	  protected readonly form = new FormGroup({
287	    amount: new FormControl('', { nonNullable: true }),
288	    date: new FormControl('', { nonNullable: true }),
289	    note: new FormControl('', { nonNullable: true }),
290	    corrects: new FormControl('', { nonNullable: true }),
291	  });
292	
293	  constructor() {
294	    this.form.valueChanges.subscribe(() => this.error.set(''));
295	  }
296	
297	  protected fieldId(field: string): string {
298	    return `claim-${this.personId()}-${field}`;
299	  }
300	
301	  /** The due fixed when it was settled, else its figure with its late charge on top. */
302	  protected dueOf(c: Claim): string {
303	    const due = claimDueCents(c, this.pctOn(), this.session.floorCentsOn, this.session.late(), roundsOn(c, this.claims()));
304	    return due === null ? NA : money(due);
305	  }
306	
307	  protected overdueOf(c: Claim): boolean {
308	    return isOverdue(c, this.session.today());
309	  }
310	
311	  /** The name of the period its date falls in, or blank when none. */
312	  protected periodOf(c: Claim): string {
313	    return periodOn(this.periods(), c.date)?.name ?? '';
314	  }
315	
316	  private headers(): Record<string, string> {
317	    return { 'X-User': this.session.user() ?? '' };
318	  }
319	
320	  private reset(): void {
321	    this.editingId.set(null);
322	    this.form.reset({ amount: '', date: '', note: '', corrects: '' }, { emitEvent: false });
323	    this.error.set('');
324	  }
325	
326	  protected edit(c: Claim): void {
327	    this.claimError.set(null);
328	    if (closedOn(this.periods(), c.date)) {
329	      this.claimError.set({ id: c.id, message: CLOSED });
330	      return;
331	    }
332	    if (c.status !== 'DRAFT') {
333	      this.claimError.set({ id: c.id, message: notEditable(c.status) });
334	      return;
335	    }
336	    this.editingId.set(c.id);
337	    this.form.setValue({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' },
338	      { emitEvent: false });
339	    this.error.set('');
340	  }
341	
342	  protected cancel(): void {
343	    this.reset();
344	  }
345	
346	  /**
347	   * Open, settle or void a claim, approve or reject (with a reason) a PENDING one, or re-settle a
348	   * SETTLED one at its figure today; a change its
349	   * status does not allow is refused.
350	   */
351	  protected async act(c: Claim, action: ClaimAction, reason = ''): Promise<void> {
352	    this.claimError.set(null);
353	    const sheet = this.session.sheetId();
354	    if (!sheet) return;
355	    const why = reason.trim().replace(/\s+/g, ' ');
356	    if (action === 'reject' && (why === '' || why.length > 200)) {
357	      this.claimError.set({ id: c.id, message: 'Give a reason for rejecting the claim (at most 200 characters).' });
358	      return;
359	    }
360	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/${action}`;
361	    const body = action === 'reject' ? { reason: why } : null;
362	    try {
363	      const claim = await firstValueFrom(this.http.post<Claim>(url, body, { headers: this.headers() }));
364	      if (this.session.sheetId() !== sheet) return;
365	      this.saved.emit(claim);
366	    } catch (e) {
367	      if (this.session.sheetId() !== sheet) return;
368	      const message = e instanceof HttpErrorResponse && e.status === 423
369	        ? CLOSED
370	        : e instanceof HttpErrorResponse && e.status === 409
371	        ? `A ${c.status} claim cannot be ${PAST[action]}.`
372	        : e instanceof HttpErrorResponse && e.status === 403
373	        ? action === 'settle'
374	          ? 'The user who opened a claim cannot settle it.'
375	          : action === 'approve' && c.openedBy === this.session.user()
376	          ? 'The user who opened a claim cannot approve it.'
377	          : action === 'resettle'
378	          ? 'Only a steward can re-settle a SETTLED claim.'
379	          : 'Only a steward can approve or reject a PENDING claim.'
380	        : 'Could not change that claim.';
381	      this.claimError.set({ id: c.id, message });
382	    }
383	  }
384	
385	  protected clearClaimError(id: number): void {
386	    if (this.claimError()?.id === id) this.claimError.set(null);
387	  }
388	
389	  /** A steward moves a DRAFT, OPEN or PENDING claim to another person; a SETTLED or VOID one cannot move. */
390	  protected async reassign(c: Claim, to: string): Promise<void> {
391	    this.claimError.set(null);
392	    const sheet = this.session.sheetId();
393	    if (!sheet) return;
394	    if (to === '') {
395	      this.claimError.set({ id: c.id, message: 'Choose another person to move the claim to.' });
396	      return;
397	    }
398	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/reassign`;
399	    try {
400	      const claim = await firstValueFrom(
401	        this.http.post<Claim>(url, { personId: Number(to) }, { headers: this.headers() }));
402	      if (this.session.sheetId() !== sheet) return;
403	      if (this.editingId() === c.id) this.reset();
404	      this.moved.emit(claim);
405	    } catch (e) {
406	      if (this.session.sheetId() !== sheet) return;
407	      const message = e instanceof HttpErrorResponse && e.status === 423
408	        ? CLOSED
409	        : e instanceof HttpErrorResponse && e.status === 409
410	        ? `A ${c.status} claim cannot be moved; only a DRAFT, OPEN or PENDING one can.`
411	        : e instanceof HttpErrorResponse && e.status === 403
412	        ? 'Only a steward can move a claim to another person.'
413	        : e instanceof HttpErrorResponse && e.status === 422
414	        ? RETIRED
415	        : 'Could not move that claim.';
416	      this.claimError.set({ id: c.id, message });
417	    }
418	  }
419	
420	  protected async save(): Promise<void> {
421	    if (this.saving) return;
422	    this.error.set('');
423	    this.claimError.set(null);
424	    const sheet = this.session.sheetId();
425	    if (!sheet) return;
426	    const raw = this.form.getRawValue();
427	    const amount = raw.amount.trim();
428	    const date = raw.date.trim();
429	    const corrects = raw.corrects.trim();
430	    if (!/^-?\d{1,12}(\.\d{1,2})?$/.test(amount)) {
431	      this.error.set('Enter an amount with at most two decimals, negative only for a correction.');
432	      return;
433	    }
434	    const correction = amount.startsWith('-') && cents(amount) < 0;
435	    if (correction ? !/^\S{1,220}$/.test(corrects) : corrects !== '') {
436	      this.error.set(correction ? CORRECTION : 'Only a correction (a negative amount) names a claim it corrects.');
437	      return;
438	    }
439	    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
440	      this.error.set('Enter a date, or leave it blank for today.');
441	      return;
442	    }
443	    const body = { amount, date: date || null, note: raw.note.trim(), corrects: corrects || null };
444	    const id = this.editingId();
445	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
446	    this.saving = true;
447	    try {
448	      const claim = await firstValueFrom(
449	        id === null
450	          ? this.http.post<Claim>(`${base}/people/${this.personId()}/claims`, body, { headers: this.headers() })
451	          : this.http.put<Claim>(`${base}/claims/${id}`, body, { headers: this.headers() }),
452	      );
453	      if (this.session.sheetId() !== sheet) return;
454	      this.saved.emit(claim);
455	      this.reset();
456	    } catch (e) {
457	      if (this.session.sheetId() !== sheet) return;
458	      if (id !== null && e instanceof HttpErrorResponse && e.status === 409) {
459	        const status = this.claims().find((c) => c.id === id)?.status;
460	        this.claimError.set({ id, message: notEditable(status) });
461	        return;
462	      }
463	      this.error.set(
464	        e instanceof HttpErrorResponse && e.status === 423
465	          ? CLOSED
466	          : e instanceof HttpErrorResponse && e.status === 422
467	          ? RETIRED
468	          : e instanceof HttpErrorResponse && e.status === 400 && correction
469	          ? CORRECTION
470	          : id === null ? 'Could not add that claim.' : 'Could not save that claim.',
471	      );
472	    } finally {
473	      this.saving = false;
474	    }
475	  }
476	}
